// Days 29-35 COMPREHENSIVE Questions — 75 Days Hard English
// MINIMUM 55+ unique questions per day
// Total: 385+ questions across Days 29-35
// Topics:
//   Day 29: Will / Shall (future predictions, promises, decisions)
//   Day 30: Would + Ought To + Dare (advanced modals)
//   Day 31: Revision Day (Days 22-30 modal verbs)
//   Day 32: Tenses Part 1 (Simple Present, Simple Past, Simple Future)
//   Day 33: Tenses Part 2 (Present Continuous, Past Continuous, Future Continuous)
//   Day 34: Tenses Part 3 (Present Perfect, Past Perfect, Future Perfect)
//   Day 35: Tenses Part 4 (Perfect Continuous tenses, all 3)
//
// ALL questions in Hindi with English answers.
// Mix of translation/mcq/fill_blank/error_detection.
// ============================================================

import type { PracticeQ } from "./day-1-questions";

// ── Compact question builder ──────────────────────────────────
const q = (
  id: string,
  subtopicId: string,
  questionText: string,
  questionType: "translation" | "mcq" | "fill_blank" | "error_detection",
  correctAnswer: string,
  explanation: string,
  hindiExplanation: string,
  points: number,
  options?: { a: string; b: string; c: string; d: string },
  hints?: { word: string; meaning: string }[]
): PracticeQ => ({
  id,
  subtopicId,
  questionText,
  questionType,
  difficulty: points <= 5 ? "beginner" : points <= 8 ? "elementary" : "intermediate",
  correctAnswer,
  explanation,
  hindiExplanation,
  optionA: options?.a,
  optionB: options?.b,
  optionC: options?.c,
  optionD: options?.d,
  wordHints: hints || [],
  points,
});

