// ── Helper: Get questions for a specific day (29-35) ─────────
export function getDays29to35Questions(
  dayNumber: number,
  subtopicId?: string
): PracticeQ[] {
  let allQuestions: PracticeQ[] = [];

  switch (dayNumber) {
    case 29: allQuestions = ALL_DAY_29_QUESTIONS; break;
    case 30: allQuestions = ALL_DAY_30_QUESTIONS; break;
    case 31: allQuestions = ALL_DAY_31_QUESTIONS; break;
    case 32: allQuestions = ALL_DAY_32_QUESTIONS; break;
    case 33: allQuestions = ALL_DAY_33_QUESTIONS; break;
    case 34: allQuestions = ALL_DAY_34_QUESTIONS; break;
    case 35: allQuestions = ALL_DAY_35_QUESTIONS; break;
    default: return [];
  }

  if (subtopicId) {
    const filtered = allQuestions.filter(q => q.subtopicId === subtopicId);
    return filtered.length > 0 ? filtered : allQuestions;
  }

  return allQuestions;
}
